//! Unified WASM artifact resolution: find, build, and install WASM components.//!//! This module consolidates all WASM artifact logic that was previously duplicated//! across `cli/tool.rs`, `registry/installer.rs`, `extensions/manager.rs`,//! `channels/wasm/bundled.rs`, and `tools/wasm/loader.rs`.//!//! # Functions//!//! - [`resolve_target_dir`] — resolve the cargo target directory for a crate//! - [`find_wasm_artifact`] — find a compiled `.wasm` by crate name across all triples//! - [`find_any_wasm_artifact`] — find any `.wasm` file (fallback when name is unknown)//! - [`build_wasm_component`] — async build via `cargo component build`//! - [`build_wasm_component_sync`] — sync build for CLI use//! - [`install_wasm_files`] — copy `.wasm` + optional `.capabilities.json` to install diruse std::path::{Path, PathBuf};use tokio::fs;/// WASM target triples to search, in priority order.const WASM_TRIPLES: &[&str] = &[    "wasm32-wasip1",    "wasm32-wasip2",    "wasm32-wasi",    "wasm32-unknown-unknown",];/// Resolve the cargo target directory for a crate.////// Checks (in order):/// 1. `CARGO_TARGET_DIR` env var (shared target dir)/// 2. `<crate_dir>/target/` (default per-crate layout)pub fn resolve_target_dir(crate_dir: &Path) -> PathBuf {    if let Ok(dir) = std::env::var("CARGO_TARGET_DIR") {        let p = PathBuf::from(dir);        // Resolve relative CARGO_TARGET_DIR against crate_dir        if p.is_relative() {            return crate_dir.join(p);        }        return p;    }    crate_dir.join("target")}/// Find a compiled WASM artifact by searching across all target triples.////// Tries exact name match first (with hyphen-to-underscore normalization),/// then falls back to searching in whichever target directory exists./// `profile` is `"release"` or `"debug"`.pub fn find_wasm_artifact(crate_dir: &Path, crate_name: &str, profile: &str) -> Option<PathBuf> {    let target_base = resolve_target_dir(crate_dir);    let snake_name = crate_name.replace('-', "_");    // Try exact name match in each target triple directory    for triple in WASM_TRIPLES {        let dir = target_base.join(triple).join(profile);        let candidates = [            dir.join(format!("{}.wasm", crate_name)),            dir.join(format!("{}.wasm", snake_name)),        ];        for candidate in &candidates {            if candidate.exists() {                return Some(candidate.clone());            }        }    }    None}/// Find any `.wasm` file in the target dirs (fallback when crate name is unknown).////// Returns the first `.wasm` found across target triples.pub fn find_any_wasm_artifact(crate_dir: &Path, profile: &str) -> Option<PathBuf> {    let target_base = resolve_target_dir(crate_dir);    for triple in WASM_TRIPLES {        let dir = target_base.join(triple).join(profile);        if !dir.is_dir() {            continue;        }        if let Ok(entries) = std::fs::read_dir(&dir) {            for entry in entries.flatten() {                let path = entry.path();                if path.extension().map(|ext| ext == "wasm").unwrap_or(false) {                    return Some(path);                }            }        }    }    None}/// Build a WASM component using `cargo-component` (async).////// Streams build output to the terminal. Returns the path to the built artifact.